def backfill_book_sync_time(apps, schema_editor):
    """已有书籍按最近进度/更新时间补 sync_updated_at, 保证首次增量拉取能取到。"""
    Book = apps.get_model("legado", "LegadoBook")
    batch = []
    for book in Book.objects.all().iterator(chunk_size=500):
        update_ms = int(book.update_time.timestamp() * 1000) if book.update_time else 0
        book.sync_updated_at = max(
            int(book.dur_chapter_time or 0),
            int(book.last_read_time or 0),
            update_ms,
        )
        batch.append(book)
        if len(batch) >= 500:
            Book.objects.bulk_update(batch, ["sync_updated_at"])
            batch.clear()
    if batch:
        Book.objects.bulk_update(batch, ["sync_updated_at"])


